INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (402, 1, '기본 상태', 'MariaDB 의 **슬로우 쿼리 로그** 는 기본으로 켜져 있을까요?', '기본값이 꺼짐이에요.', NULL, NULL, '[]', 'choice', '["기본으로 켜져 있고 10초 넘는 쿼리를 기록한다", "기본으로 켜져 있고 모든 쿼리를 기록한다", "기본으로 꺼져 있다", "쿼리가 100개 쌓이면 자동으로 켜진다"]', 2, 'MariaDB 문서는 슬로우 쿼리 로그가 기본으로 비활성이며, slow_query_log 변수(10.11 부터 log_slow_query)를 1 로 해야 켜진다고 설명합니다.', NULL, NULL, NULL, '[{"title": "MariaDB 슬로우 쿼리 로그", "url": "https://mariadb.com/kb/en/slow-query-log-overview/"}]'),
  (402, 2, '동적으로 켜기', '서버를 **재시작하지 않고** SET GLOBAL 로 슬로우 로그를 켜면 어떻게 될까요?', '바로 켜지지만 영구적이진 않아요.', NULL, NULL, '[]', 'choice', '["재시작해야만 켜진다", "즉시 켜지지만 다음 서버 재시작까지만 유지된다", "즉시 켜지고 재시작 후에도 계속 유지된다", "실행 중에는 바꿀 수 없다는 오류가 난다"]', 1, '문서는 SET GLOBAL slow_query_log=1 이 로깅을 즉시 켜지만 다음 서버 재시작까지만 유효하고, 영구로 하려면 옵션 파일에 적고 재시작해야 한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "MariaDB 슬로우 쿼리 로그", "url": "https://mariadb.com/kb/en/slow-query-log-overview/"}]'),
  (402, 3, 'long_query_time', '**long_query_time** 의 기본값은 얼마일까요?', '초 단위예요.', NULL, NULL, '[]', 'choice', '["10초", "1초", "0.1초", "60초"]', 0, '문서는 long_query_time 의 기본값이 10(초)이며 밀리초 단위 소수도 줄 수 있다고 설명합니다. 10.11 부터 log_slow_query_time 으로 이름이 바뀌었습니다.', NULL, NULL, NULL, '[{"title": "MariaDB 슬로우 쿼리 로그", "url": "https://mariadb.com/kb/en/slow-query-log-overview/"}]'),
  (402, 4, '로그 파일 이름', '슬로우 쿼리 로그 파일의 **기본 이름과 위치** 는 어떻게 될까요?', '호스트 이름이 들어가요.', NULL, NULL, '[]', 'choice', '["/var/log 아래의 slow.log 로 고정", "데이터 디렉터리의 mysql.err 파일", "홈 디렉터리 아래의 slow.txt 파일", "데이터 디렉터리의 ${hostname}-slow.log"]', 3, '문서는 기본으로 ${hostname}-slow.log 에 기록되고 데이터 디렉터리에 저장되며 동적으로 바꿀 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "MariaDB 슬로우 쿼리 로그", "url": "https://mariadb.com/kb/en/slow-query-log-overview/"}]'),
  (402, 5, 'log_output', '**log_output** 에서 슬로우 로그의 **기본 저장 방식** 은 무엇일까요?', '파일이 기본이에요.', NULL, NULL, '[]', 'choice', '["TABLE (mysql.slow_log 테이블)", "SYSLOG (시스템 로그)", "FILE (파일)", "NONE (저장하지 않음)"]', 2, '문서는 log_output 값이 FILE 또는 TABLE 이며 파일 로깅이 기본이라고 설명합니다. TABLE 이면 mysql.slow_log 테이블에 기록합니다.', NULL, NULL, NULL, '[{"title": "MariaDB 슬로우 쿼리 로그", "url": "https://mariadb.com/kb/en/slow-query-log-overview/"}]'),
  (402, 6, 'min_examined_row_limit', '**min_examined_row_limit** 는 무엇을 정할까요?', '검사한 행 수 기준이에요.', NULL, NULL, '[]', 'choice', '["슬로우 로그 파일이 가질 수 있는 최대 줄 수", "슬로우로 기록되려면 검사해야 하는 최소 행 수", "쿼리가 반환할 수 있는 최대 행 수를 뜻한다", "로그를 삭제하기 전에 보관하는 행 수"]', 1, '문서는 min_examined_row_limit 를 쿼리가 슬로우로 간주되기 위해 검사해야 하는 최소 행 수로 설명합니다. 10.11 부터 log_slow_min_examined_row_limit 입니다.', NULL, NULL, NULL, '[{"title": "MariaDB 슬로우 쿼리 로그", "url": "https://mariadb.com/kb/en/slow-query-log-overview/"}]'),
  (402, 7, '인덱스 없는 쿼리', '**log_queries_not_using_indexes** 를 켜면 무엇이 기록될까요?', '시간과 무관해요.', NULL, NULL, '[]', 'choice', '["인덱스 없는 쿼리가 시간과 무관하게 기록된다", "인덱스를 쓰는 쿼리만 골라서 기록된다", "10초를 넘는 쿼리만 골라서 기록된다", "오류가 난 쿼리만 골라서 기록된다"]', 0, '문서는 log_queries_not_using_indexes 를 ON 으로 하면 실행 시간과 무관하게 인덱스를 쓰지 않는 쿼리를 기록하며, 행 수 제한과 함께 쓰면 잡음을 줄일 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "MariaDB 슬로우 쿼리 로그", "url": "https://mariadb.com/kb/en/slow-query-log-overview/"}]'),
  (402, 8, 'log_slow_verbosity', '**log_slow_verbosity** 는 무엇을 정할까요?', '추가 정보예요.', NULL, NULL, '[]', 'choice', '["로그를 남길 쿼리가 가져야 하는 최소 길이", "로그 파일을 압축해서 보관할지 여부", "로그를 보내 줄 원격 서버의 주소", "로그에 넣을 선택 정보(query_plan 등)"]', 3, '문서는 log_slow_verbosity 가 쿼리별로 로그에 포함할 선택 정보를 정하며 예로 query_plan,explain,engine 과 full 을 든다고 설명합니다.', NULL, NULL, NULL, '[{"title": "MariaDB 슬로우 쿼리 로그", "url": "https://mariadb.com/kb/en/slow-query-log-overview/"}]'),
  (402, 9, 'log_slow_rate_limit', '**log_slow_rate_limit** 는 무엇을 할까요?', '로그가 너무 많을 때 써요.', NULL, NULL, '[]', 'choice', '["슬로우 로그 파일의 크기를 제한한다", "느린 쿼리를 강제로 중단시킨다", "슬로우 쿼리 중 일부 비율만 기록되게 제한한다", "쿼리의 실행 속도를 제한한다"]', 2, '문서는 log_slow_rate_limit 가 슬로우 쿼리의 일부 비율만 기록되도록 로깅을 조절하는 변수라고 설명하며 SET GLOBAL log_slow_rate_limit=5 를 예로 듭니다.', NULL, NULL, NULL, '[{"title": "MariaDB 슬로우 쿼리 로그", "url": "https://mariadb.com/kb/en/slow-query-log-overview/"}]'),
  (402, 10, '로그 요약 도구', '슬로우 쿼리 로그를 **요약** 해 주는 도구입니다. 빈칸을 채우세요.', '"dumpslow" 가 들어가요.', NULL, NULL, '[]', 'fill', '["mariadb-dumpslow", "mariadb-dump", "mariadb-admin", "mariadb-check"]', NULL, '문서는 슬로우 쿼리 로그를 요약하는 도구로 mariadb-dumpslow 를 권합니다.', '[0]', '{0} /var/lib/mysql/host-slow.log', NULL, '[{"title": "MariaDB 슬로우 쿼리 로그", "url": "https://mariadb.com/kb/en/slow-query-log-overview/"}]'),
  (402, 11, '로그 기본 출력', '슬로우 로그의 **기본 출력 방식** 입니다. 빈칸을 채우세요.', '테이블이 아니에요.', NULL, NULL, '[]', 'fill', '["FILE", "TABLE", "NONE", "SYSLOG"]', NULL, 'log_output 의 기본은 FILE 입니다. TABLE 로 바꾸면 mysql.slow_log 테이블에 기록됩니다.', '[0]', 'SET GLOBAL log_output = {0};', NULL, '[{"title": "MariaDB 슬로우 쿼리 로그", "url": "https://mariadb.com/kb/en/slow-query-log-overview/"}]'),
  (402, 12, '슬로우 쿼리 조사 순서', '느린 쿼리를 찾는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '켜기 → 기준 → 수집 → 요약이에요.', NULL, NULL, '[]', 'order', '["SET GLOBAL 로 슬로우 쿼리 로그를 켠다", "long_query_time 으로 기록할 기준을 정한다", "서비스를 돌려 느린 쿼리가 로그에 쌓이게 한다", "mariadb-dumpslow 로 로그를 요약해 느린 쿼리를 고른다"]', NULL, '문서가 설명한 켜기·기준·요약 도구를 이은 큰 줄기입니다. 영구 적용은 옵션 파일과 재시작이 필요합니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "MariaDB 슬로우 쿼리 로그", "url": "https://mariadb.com/kb/en/slow-query-log-overview/"}]');
